import { useEffect, useState } from "react";
import { api } from "../api/manuscriptApi";
import { useParams, useNavigate } from "react-router-dom";

export default function ManuscriptForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [authors, setAuthors] = useState([]); // MUST BE ARRAY

  const [form, setForm] = useState({
    title: "",
    abstract: "",
    keywords: "",
    reference_list: "",
    cover_letter: "",
    manuscript_file: null,
    supplementary_materials: [],
    plagiarism_score: 0,
    author_id: "",
    journal_id: "",
    assigned_editor_id: "",
    status: "Submitted"
  });

  // -------------------------------------------
  // LOAD AUTHORS
  // -------------------------------------------
  useEffect(() => {
    const token = localStorage.getItem("token");

    api
      .get("/authors", {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then((res) => {
        console.log("Authors API Response:", res.data);

        const list =
          Array.isArray(res.data)
            ? res.data
            : res.data.data || res.data.authors || [];

        setAuthors(list);
      })
      .catch((err) => {
        console.error("Error loading authors", err);
      });
  }, []);

  // -------------------------------------------
  // IF EDIT MODE – LOAD MANUSCRIPT
  // -------------------------------------------
  useEffect(() => {
    if (method === "edit") {
      api.get(`/${id}`).then((res) => {
        const m = res.data;
        setForm({
          ...m,
          keywords: m.keywords?.join(",") || "",
          supplementary_materials: []
        });
      });
    }
  }, [id, method]);

  // -------------------------------------------
  // HANDLE SUBMIT
  // -------------------------------------------
  const handleSubmit = async (e) => {
    e.preventDefault();
    const fd = new FormData();

    Object.entries(form).forEach(([k, v]) => {
      if (k === "manuscript_file" && v) fd.append(k, v);
      else if (k === "supplementary_materials" && v.length > 0)
        Array.from(v).forEach((file) => fd.append("supplementary_materials", file));
      else fd.append(k, v);
    });

    try {
      const token = localStorage.getItem("token");

      if (method === "create") {
        await api.post("/", fd, {
          headers: { Authorization: `Bearer ${token}` }
        });
      } else {
        await api.put(`/${id}`, fd, {
          headers: { Authorization: `Bearer ${token}` }
        });
      }

      navigate("/journal/list");

    } catch (err) {
      console.error("Error submitting manuscript:", err);
      alert("Error submitting manuscript. Check console for details.");
    }
  };

  return (
    <div className="container mt-4">
      <h3>{method === "create" ? "Create Manuscript" : "Edit Manuscript"}</h3>

      <form onSubmit={handleSubmit} className="row g-3">

        {/* Title */}
        <div className="col-12">
          <input
            className="form-control"
            placeholder="Title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            required
          />
        </div>

        {/* Abstract */}
        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Abstract"
            value={form.abstract}
            onChange={(e) => setForm({ ...form, abstract: e.target.value })}
            rows={4}
            required
          />
        </div>

        {/* Authors Dropdown */}
        <div className="col-md-6">
          <label className="form-label">Select Author</label>
          <select
            className="form-control"
            value={form.author_id}
            onChange={(e) => setForm({ ...form, author_id: e.target.value })}
            required
          >
            <option value="">-- Select Author --</option>

            {Array.isArray(authors) &&
              authors.map((a) => (
                <option key={a.id} value={a.id}>
                  {a.name}
                </option>
              ))}
          </select>
        </div>

        {/* Other fields */}
        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Reference List"
            value={form.reference_list}
            onChange={(e) => setForm({ ...form, reference_list: e.target.value })}
            rows={4}
          />
        </div>

        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Cover Letter"
            value={form.cover_letter}
            onChange={(e) => setForm({ ...form, cover_letter: e.target.value })}
            rows={3}
          />
        </div>

        {/* Keywords */}
        <div className="col-12">
          <input
            className="form-control"
            placeholder="Keywords (comma separated)"
            value={form.keywords}
            onChange={(e) => setForm({ ...form, keywords: e.target.value })}
          />
        </div>

        {/* File Upload */}
        <div className="col-12">
          <input
            type="file"
            className="form-control"
            onChange={(e) => setForm({ ...form, manuscript_file: e.target.files[0] })}
            accept=".pdf,.doc,.docx"
          />
        </div>

        {/* Submit */}
        <div className="col-12">
          <button className="btn btn-primary w-100">Save Manuscript</button>
        </div>
      </form>
    </div>
  );
}
